import React from 'react'
import ReactApexChart from 'react-apexcharts'
import './styles.css'

const ApexChart = () => {
  const [state, setState] = React.useState({
    series: [44, 25, 18, 13],
    options: {
      chart: {
        type: 'donut',
        width: 420,
      },
      labels: [
        'Marguerite Tillman',
        'Gabriel Barton',
        'Kathleen Abernathy',
        'Devon Reyes',
      ],
      colors: ['#0EA5E9', '#14B8A6', '#F59E0B', '#F43F5E'],
      plotOptions: {
        pie: {
          // Round the corners of every slice (px)
          borderRadius: 12,
          // Leave a gap between adjacent slices (px)
          spacing: 5,
          donut: {
            size: '68%',
            labels: {
              show: true,
              total: {
                show: true,
                label: 'Total Orders',
              },
            },
          },
        },
      },
      stroke: {
        width: 0,
      },
      dataLabels: {
        enabled: false,
      },
      legend: {
        position: 'bottom',
      },
      title: {
        text: 'Orders by sales team',
        align: 'left',
      },
      responsive: [
        {
          breakpoint: 480,
          options: {
            chart: {
              width: 320,
            },
          },
        },
      ],
    },
  })

  return (
    <div>
      <div id="chart">
        <ReactApexChart
          options={state.options}
          series={state.series}
          type="donut"
          width={420}
        />
      </div>
    </div>
  )
}

export default ApexChart
